int main(){
    constexpr Count mod=4294967291u;constexpr int W=TARGET_W,L=LOW_LUT_K;static_assert(W<=12,"closure-zero selftest uses small width");int visible=0;cudaError_t ce=cudaGetDeviceCount(&visible);if(ce!=cudaSuccess||visible<1){std::cout<<"bucket-closure-zero-selftest SKIP no CUDA device\n";return 0;}ck(cudaSetDevice(0),"zc set device");
    build_full_dp();G_FACTOR=build_factor_tables();StorageFactorHost storage=build_storage_factor_tables(G_FACTOR);
    uint64_t key4_checked=0;for(uint32_t code:storage.low_all_codes){uint32_t a=gpu_direct_ternary_key_host(code,LOW_LUT_K),b=bkcz_ternary_key4_legal<LOW_LUT_K>(code);if(a!=b){std::cerr<<"chunked LOW ternary key mismatch code="<<code<<" old="<<a<<" new="<<b<<'\n';return 8;}++key4_checked;}for(uint32_t code:storage.high_all_codes){uint32_t a=gpu_direct_ternary_key_host(code,HIGH_LUT_K),b=bkcz_ternary_key4_legal<HIGH_LUT_K>(code);if(a!=b){std::cerr<<"chunked HIGH ternary key mismatch code="<<code<<" old="<<a<<" new="<<b<<'\n';return 9;}++key4_checked;}
