    auto g=bkft_make_grid(ms,bs,im,ib,storage,layout,owner,phy);zc_forward_low(g,layout,phy,dt);if(!bkft_compare("zero-forward-low",g,ms,bs,flm,flb,storage,layout,owner,phy))return 10;g=bkft_make_grid(ms,bs,im,ib,storage,layout,owner,phy);zc_forward_high(g,layout,phy,dt);if(!bkft_compare("zero-forward-high",g,ms,bs,fhm,fhb,storage,layout,owner,phy))return 11;g=bkft_make_grid(ms,bs,im,ib,storage,layout,owner,phy);zc_reverse_low(g,layout,phy,dt);if(!bkft_compare("zero-reverse-low",g,ms,bs,rlm,rlb,storage,layout,owner,phy))return 12;g=bkft_make_grid(ms,bs,im,ib,storage,layout,owner,phy);zc_reverse_high(g,layout,phy,dt);if(!bkft_compare("zero-reverse-high",g,ms,bs,rhm,rhb,storage,layout,owner,phy))return 13;
